import { defineComponent, h } from 'vue';
import { breadcrumbStyleKeys } from '../lib/core';
import styles from './breadcrumb.module.scss';

function renderChevronRight() {
	return h(
		'svg',
		{
			xmlns: 'http://www.w3.org/2000/svg',
			viewBox: '0 0 24 24',
			fill: 'none',
			stroke: 'currentColor',
			'stroke-width': '2',
			'stroke-linecap': 'round',
			'stroke-linejoin': 'round',
		},
		[h('path', { d: 'm9 18 6-6-6-6' })],
	);
}

function renderMoreHorizontal() {
	return h(
		'svg',
		{
			class: styles[breadcrumbStyleKeys.ellipsisIcon],
			xmlns: 'http://www.w3.org/2000/svg',
			viewBox: '0 0 24 24',
			fill: 'currentColor',
		},
		[h('circle', { cx: '12', cy: '12', r: '1' }), h('circle', { cx: '19', cy: '12', r: '1' }), h('circle', { cx: '5', cy: '12', r: '1' })],
	);
}

export const Breadcrumb = defineComponent({
	name: 'Breadcrumb',
	setup(_props, { slots }) {
		return () => h('nav', { 'aria-label': 'breadcrumb', class: styles[breadcrumbStyleKeys.root] }, slots.default?.());
	},
});

export const BreadcrumbList = defineComponent({
	name: 'BreadcrumbList',
	setup(_props, { slots }) {
		return () => h('ol', { class: styles[breadcrumbStyleKeys.list] }, slots.default?.());
	},
});

export const BreadcrumbItem = defineComponent({
	name: 'BreadcrumbItem',
	setup(_props, { slots }) {
		return () => h('li', { class: styles[breadcrumbStyleKeys.item] }, slots.default?.());
	},
});

export const BreadcrumbLink = defineComponent({
	name: 'BreadcrumbLink',
	props: {
		href: String,
	},
	setup(props, { slots, attrs }) {
		return () => h('a', { ...attrs, href: props.href, class: [styles[breadcrumbStyleKeys.link], attrs.class] }, slots.default?.());
	},
});

export const BreadcrumbPage = defineComponent({
	name: 'BreadcrumbPage',
	setup(_props, { slots }) {
		return () => h('span', { role: 'link', 'aria-disabled': 'true', 'aria-current': 'page', class: styles[breadcrumbStyleKeys.page] }, slots.default?.());
	},
});

export const BreadcrumbSeparator = defineComponent({
	name: 'BreadcrumbSeparator',
	setup(_props, { slots }) {
		return () =>
			h('li', { role: 'presentation', 'aria-hidden': 'true', class: styles[breadcrumbStyleKeys.separator] }, slots.default ? slots.default() : [renderChevronRight()]);
	},
});

export const BreadcrumbEllipsis = defineComponent({
	name: 'BreadcrumbEllipsis',
	setup(_props) {
		return () =>
			h('span', { role: 'presentation', 'aria-hidden': 'true', class: styles[breadcrumbStyleKeys.ellipsis] }, [
				renderMoreHorizontal(),
				h('span', { class: styles[breadcrumbStyleKeys.srOnly] }, 'More'),
			]);
	},
});

export default Breadcrumb;

@use '../../../styles/variables/colors' as *;

.root {
	// 导航容器无额外样式
}

.list {
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	gap: var(--tile-breadcrumb-gap, $spacing-1_5);
	font-size: var(--tile-breadcrumb-font-size, $text-sm);
	color: var(--tile-breadcrumb-foreground, $muted-foreground);
	word-break: break-word;

	@media (min-width: 640px) {
		gap: var(--tile-breadcrumb-gap, $spacing-2_5);
	}
}

.item {
	display: inline-flex;
	align-items: center;
	gap: $spacing-1_5;
}

.link {
	transition: color $transition-fast;

	&:hover {
		color: var(--tile-breadcrumb-active-foreground, $foreground);
	}
}

.page {
	font-weight: var(--tile-breadcrumb-page-font-weight, $font-normal);
	color: var(--tile-breadcrumb-active-foreground, $foreground);
}

.separator {
	display: inline-flex;
	align-items: center;
	color: var(--tile-breadcrumb-separator, inherit);

	> svg {
		width: var(--tile-breadcrumb-separator-size, 0.875rem);
		height: var(--tile-breadcrumb-separator-size, 0.875rem);
	}
}

.ellipsis {
	display: flex;
	width: 2.25rem;
	height: 2.25rem;
	align-items: center;
	justify-content: center;
}

.ellipsisIcon {
	width: 1rem;
	height: 1rem;
}

.srOnly {
	position: absolute;
	width: 1px;
	height: 1px;
	padding: 0;
	margin: -1px;
	overflow: hidden;
	clip: rect(0, 0, 0, 0);
	white-space: nowrap;
	border: 0;
}
